  const ref = useRef<HTMLDivElement>(null);
  const html = useMemo(() => transform(markdown, { allowHTML: false, breaks: true, linkify: true }).result.html, [markdown]);

  useEffect(() => {
    void ref.current;
  }, [html]);

  return <YfmStaticView ref={ref} html={html} noListReset />;
}
